## ---- 01: Loading the Servicer Loan Tape (User Helper)  (qmd line 383) ----------------

library(dplyr)

# Helper: load and clean a loan-tape panel. Servicers publish these
# as monthly files; here it reads the book's sample dataset
# (Chapter 7), which carries the same status and vintage fields a
# servicer extract would.
load_servicer_tape <- function(path, start_year = 2010) {
  raw <- readr::read_csv(path)
  raw %>%
    filter(year >= start_year) %>%
    mutate(default_event = status %in% c("CHARGE_OFF","LIQUIDATION"),
           prepay_event  = status == "PAID_IN_FULL")
}

loan_panel <- load_servicer_tape("data/sample_loan_panel.csv")
glimpse(loan_panel)


## ---- 02: Loan-Age Default Curve  (qmd line 404) --------------------------------------

library(survival)
library(survminer)

km_default <- survfit(Surv(age_months, default_event) ~ 1,
                      data = loan_panel)
ggsurvplot(km_default, fun = "event", conf.int = TRUE,
           legend = "none", xlab = "Months",
           ylab = "Cumulative default incidence",
           title = "Loan-Pool Lifetime Default Curve")


