## ---- 04: Cox PH Default Model  (qmd line 432) ----------------------------------------

# Seasoning needs no covariate here: in a Cox model the age profile
# of default is the baseline hazard itself; covariates shift it
fit_default <- coxph(
  Surv(age_months, default_event) ~ coupon + log(orig_balance) +
    factor(sector_grp) + state_unemp,
  data = loan_panel
)
summary(fit_default)


## ---- 05: Common-Factor Default Simulation  (qmd line 445) ----------------------------

n_paths <- 500; n_months <- 360
F_path  <- matrix(rnorm(n_paths * n_months), n_paths, n_months)

# Per-loan hazard with common factor loading
simulate_default <- function(loan_attrs, F_path, lambda_F = 0.4) {
  base_h <- predict(fit_default, loan_attrs, type = "expected")
  log_h  <- log(base_h) + lambda_F * F_path
  h_path <- exp(log_h)
  smm    <- 1 - exp(-h_path)
  matrix(rbinom(length(smm), 1, smm), nrow = nrow(smm))
}


## ---- 06: Recovery Stream Modeling  (qmd line 461) ------------------------------------

# credit guaranty + residual recovery
recovery_stream <- function(default_amount, guaranteed_pct = 0.75,
                            gp_haircut = 0.02, residual_lgd = 0.45,
                            gp_lag = 6, residual_lag = 12,
                            residual_window = 24) {
  guarantied <- default_amount * guaranteed_pct * (1 - gp_haircut)
  residual   <- default_amount * (1 - guaranteed_pct) * (1 - residual_lgd)
  list(gp = c(rep(0, gp_lag - 1), guarantied),
       residual = c(rep(0, residual_lag - 1),
                    rep(residual / residual_window, residual_window)))
}


## ---- 07: LGD Beta Distribution  (qmd line 477) ---------------------------------------

library(actuar)
# Calibrate Beta(alpha, beta) to mean and variance of historical LGD
calibrate_beta <- function(mean_lgd, var_lgd) {
  m <- mean_lgd; v <- var_lgd
  alpha <- m * (m * (1 - m) / v - 1)
  beta  <- (1 - m) * (m * (1 - m) / v - 1)
  list(alpha = alpha, beta = beta)
}

params <- calibrate_beta(mean_lgd = 0.42, var_lgd = 0.04)
sim_lgd <- rbeta(1000, params$alpha, params$beta)

library(ggplot2)
ggplot(data.frame(lgd = sim_lgd), aes(lgd)) +
  geom_histogram(bins = 30, fill = "steelblue", colour = "white") +
  labs(x = "Simulated LGD", y = "Count") +
  theme_minimal()


