# CCAR severely-adverse: unemployment +5pp, GDP -7%
stress_data <- loan_panel %>% mutate(state_unemp = state_unemp + 0.05)
stress_h    <- predict(fit_default, newdata = stress_data,
                       type = "risk")
mean(stress_h) / mean(predict(fit_default, loan_panel, type = "risk"))
